CREATE TABLE IF NOT EXISTS "Users" ("id" SERIAL, "firstName" VARCHAR(255), "lastName" VARCHAR(255), "emailAddress" VARCHAR(255) UNIQUE, "dateOfBirth" DATE, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL, "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "Posts" ("id" SERIAL, "UserId" INTEGER REFERENCES "Users" ("id") ON DELETE CASCADE ON UPDATE CASCADE, "postTitle" VARCHAR(255), "postBody" TEXT, "isPublished" BOOLEAN DEFAULT false, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL, "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "Likes" ("id" SERIAL, "PostId" INTEGER NOT NULL REFERENCES "Posts" ("id") ON DELETE CASCADE ON UPDATE CASCADE, "UserId" INTEGER NOT NULL REFERENCES "Users" ("id") ON DELETE CASCADE ON UPDATE CASCADE, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY ("id"), UNIQUE ("PostId", "UserId"));
